export type HeadlineKey = keyof Phrasebook['headlines'];

/**
 * Which phrasebook headline best describes a turn.
 *
 * Shared by the server's proactive banner and the in-browser fallback so the
 * two can never greet a fisher with different wording for the same situation.
 */
const HEADLINE_BY_INTENT: Record<string, HeadlineKey> = {
  FIND_PFZ: 'pfz',
  SAFETY_ASSESSMENT: 'safety',
  TIDE_WEATHER_SEA: 'tide',
  HAZARD_ALERTS: 'alerts',
  PFZ_HOTSPOTS: 'hotspots',
  SAFE_ROUTE: 'route',
  PRODUCTIVITY_DIAGNOSIS: 'productivity',
  AVOID_ZONES: 'avoid',
  GEOFENCE_PROXIMITY: 'geofence',
  OCEAN_STATE: 'ocean',
  WEATHER_BRIEF: 'weather',
  GENERAL_MARINE: 'generic',
};

export const headlineKeyFor = (intent: string): HeadlineKey =>
  HEADLINE_BY_INTENT[intent] ?? 'generic';

/**
 * Values for the `{slot}` placeholders in a headline template.
 *
 * All eleven phrasebooks use the same slot names for a given headline, so one
 * record type covers every language.
 */
export type HeadlineSlots = Record<string, string | number>;

/**
 * Fill the `{slot}` placeholders in a phrasebook template.
 *
 * The templates keep units in the prose ("in {depth} m of water") so that the
 * slot values stay bare numbers, names and already-localised words, and so that
 * a translated sentence is not assembled out of fragments here.
 *
 * A placeholder with no matching slot is dropped rather than left in place. A
 * headline that renders as "in {depth} m of water" is worse than one that
 * renders as "in 45 m of water" or, failing that, "in water": these strings are
 * shown verbatim to somebody deciding whether to launch a boat, so a half-filled
 * template must never survive to the screen.
 */
export function fillTemplate(template: string, slots: HeadlineSlots): string {
  return template
    // Only the braces are consumed, never the surrounding space: "for {harbor}"
    // must become "for Kochi", not "forKochi". A slot with no value leaves a
    // gap, which the two passes below close up.
    .replace(/\{(\w+)\}/g, (_match, key: string) => {
      const value = slots[key];
      return value === undefined || value === '' ? '' : String(value);
    })
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/[ \t]+([.,;:!?])/g, '$1')
    .trim();
}

/** Render one headline of a phrasebook with all of its slots filled in. */
export function renderHeadline(book: Phrasebook, key: HeadlineKey, slots: HeadlineSlots): string {
  return fillTemplate(book.headlines[key], slots);
}

export function getPhrasebook(language: LanguageCode): Phrasebook {
  return PHRASEBOOKS[language] ?? PHRASEBOOKS['en-IN'];
}

export const riskWord = (book: Phrasebook, level: RiskLevel): string =>
  book.riskWords[['LOW', 'MODERATE', 'HIGH', 'SEVERE'].indexOf(level)];

export const qualityWord = (book: Phrasebook, quality: 'GOOD' | 'FAIR' | 'POOR'): string =>
  quality === 'GOOD' ? book.ui.qualityGoodWord : quality === 'FAIR' ? book.ui.qualityFairWord : book.ui.qualityPoorWord;

export const trendWord = (
  book: Phrasebook,
  trend: 'increasing' | 'stable' | 'decreasing',
): string => book.trendWords[['increasing', 'stable', 'decreasing'].indexOf(trend)];

export const productivityWord = (book: Phrasebook, level: ProductivityClass): string =>
  book.productivityWords[['EXCELLENT', 'GOOD', 'FAIR', 'POOR'].indexOf(level)];

export const seaStateWord = (book: Phrasebook, waveHeightMeters: number): string => {
  const code = describeSeaState(waveHeightMeters).code;
  return book.seaStates[Math.min(code, book.seaStates.length - 1)];
};

export const HORIZON_INDEX: Record<string, number> = {
  NOW: 0,
  TODAY: 1,
  TOMORROW: 2,
  NEXT_3_DAYS: 3,
  WEEK: 4,
};

export const horizonWord = (book: Phrasebook, horizon: keyof typeof HORIZON_INDEX): string =>
  book.horizon[HORIZON_INDEX[horizon] ?? 0];

export const formatTideEvent = (event: TidalData | undefined): string => {
  if (!event) return '—';
  return `${event.label} (${event.heightMeters.toFixed(2)} m)`;
};

export const SUPPORTED_PHRASEBOOK_LANGUAGES = Object.keys(PHRASEBOOKS) as LanguageCode[];
